function longestShared(a: string, b: string): number {
  const go = (i: number, j: number): number => {
    if (i === 0 || j === 0) return 0;
    if (a[i - 1] === b[j - 1]) return go(i - 1, j - 1) + 1;
    return Math.max(go(i - 1, j), go(i, j - 1));
  };
  return go(a.length, b.length);
}

